<?= view('layouts/header') ?><h1>User Accounts</h1><a class="btn" href="<?= site_url('users/new') ?>">New user</a><table><tr><th>Username</th><th>Actions</th></tr><?php foreach($items as $item): ?><tr><td><?= esc($item['username']) ?></td><td><a href="<?= site_url('users/'.$item['id'].'/edit') ?>">Edit</a> <?php if((int)$item['id']!==(int)session('user_id')): ?><form class="inline" method="post" action="<?= site_url('users/'.$item['id'].'/delete') ?>" onsubmit="return confirm('Delete user?')"><?= csrf_field() ?><button>Delete</button></form><?php endif ?></td></tr><?php endforeach ?></table><?= view('layouts/footer') ?>